"""Frozen Russian Q5 question inventory for all native RuSERRC aspects."""

QUESTIONS = {
    "task": ("Какая задача решается в работе?", "Какую задачу рассматривают авторы?", "Решению какой задачи посвящена работа?", "Какая исследовательская задача поставлена в статье?", "Какую проблему решает описанная работа?"),
    "goal": ("Какова цель работы?", "Какую цель ставят авторы работы?", "Для достижения какой цели выполнено исследование?", "Какова основная цель исследования?", "Чего стремятся достичь в работе?"),
    "contribution": ("Каков основной вклад работы?", "Какой вклад вносит эта работа?", "Что нового предложено или разработано авторами?", "Каков основной результат, представленный авторами?", "В чём состоит вклад данного исследования?"),
    "method": ("Какой метод используется или предлагается в работе?", "Какой метод или модель применяют либо предлагают авторы?", "Какой подход используется для решения задачи?", "Какой метод разработан или применён в работе?", "С помощью какого метода выполнено исследование?"),
    "tool": ("Какой инструмент используется в работе?", "Какое средство или программный инструмент применён?", "Какой инструмент используют авторы?", "С помощью какого инструмента выполнена работа?", "Какое программное или техническое средство используется?"),
    "use": ("Для чего используется описанный подход?", "Для какого применения предназначен описанный подход?", "Для чего авторы используют предложенное решение?", "Каково назначение описанного метода или средства?", "В какой задаче применяется представленное решение?"),
    "advantage": ("Какое преимущество описано в работе?", "В чём преимущество предложенного решения?", "Какое достоинство отмечают авторы?", "Чем предложенный подход лучше или полезнее?", "Какой положительный эффект даёт описанное решение?"),
    "example": ("Какой пример приведён в работе?", "Какой случай приводится в качестве примера?", "Что авторы приводят как пример?", "Какой иллюстративный пример описан?", "На каком примере демонстрируется подход?"),
    "conclusion": ("Какой вывод сделан в работе?", "К какому выводу пришли авторы?", "Что следует из результатов работы?", "Каков основной итог исследования?", "Какое заключение сформулировано авторами?"),
}

ASPECTS = tuple(QUESTIONS)


def validate_questions() -> None:
    if len(QUESTIONS) != 9:
        raise ValueError("Russian Q5 must contain exactly nine aspects")
    for aspect, questions in QUESTIONS.items():
        if len(questions) != 5 or len(set(questions)) != 5 or any(not q.strip() for q in questions):
            raise ValueError(f"invalid Q5 inventory for {aspect}")

